selected.compute:
options = read('/input/options')
ids = [row['id'] for row in options]
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(ids, k):
        candidate = list(group)
        if valid(candidate):
            result = candidate
            break
    if result:
        break

selected.effects:
if exists('/output/selection'):
    existing = read('/output/selection')
    if valid(existing):
        result = existing
    else:
        result = []
else:
    if valid(result):
        write('/output/selection', result)
if valid(result):
    delivery = receipt('report')
    if delivery == 'unattempted':
        send('report', 'team', result)
    elif delivery == 'unknown':
        state = status('report')
